// The simulated students you can pick. The second profile is generated by a small
// formula rather than typed by hand: same shape, different story and budget.

import { semester, snapshot, student, transactions } from "./sampleStudent";
import { addDays } from "@/lib/dates";
import type { StudentProfile, Transaction } from "@/lib/types";
import type { PolicyLimits } from "@/lib/policy/purchasePolicy";

export interface SimulatedProfile {
  id: string;
  student: StudentProfile;
  transactions: Transaction[];
  limits: PolicyLimits;
}

function buildCommuterTransactions(): Transaction[] {
  const rows: Omit<Transaction, "id">[] = [];
  const add = (
    date: string,
    merchant: string,
    category: Transaction["category"],
    amountCents: number,
    account: Transaction["account"] = "Debit card",
  ) =>
    rows.push({
      date,
      merchant,
      category,
      amountCents,
      account,
      direction: category === "income" ? "credit" : "debit",
    });

  add(semester.startDate, "Larkspur Campus Bookstore", "books", 13240);
  add(semester.startDate, "Metro Student Transit Pass", "transport", 4500);

  for (let week = 1; week <= semester.totalWeeks; week++) {
    const monday = addDays(semester.startDate, (week - 1) * 7);
    // Formula-based variation keeps the data identical on every run.
    add(addDays(monday, 1), "Quad Coffee Co.", "dining", 450 + (week * 37) % 140, "Campus card");
    add(addDays(monday, 2), "Corner Greens Market", "groceries", 2100 + (week * 211) % 900);
    add(addDays(monday, 3), "Commons Dining Hall", "dining", 1175, "Campus card");
    if (week % 2 === 0) {
      add(addDays(monday, 4), "Rec Center Front Desk payroll", "income", 16200);
    }
    if (week % 3 === 0) {
      add(addDays(monday, 5), "CityHop Rides", "transport", 1100 + (week * 53) % 500);
    }
    if (week % 4 === 1) {
      add(addDays(monday, 6), "Streamly", "subscriptions", 799);
    }
  }

  return rows
    .sort((a, b) => a.date.localeCompare(b.date))
    .map((row, index) => ({
      ...row,
      id: `theo_txn_${String(index + 1).padStart(3, "0")}`,
    }));
}

export const profiles: SimulatedProfile[] = [
  {
    id: "maya",
    student,
    transactions,
    limits: { challengeAboveCents: 15_000, hardLimitCents: 60_000 },
  },
  {
    id: "theo",
    student: {
      name: "Theo Nakamura",
      year: "Junior",
      major: "Civil Engineering",
      housing: "Commutes from home",
      school: "Larkspur State University",
      semesterBudgetCents: 130_000,
    },
    transactions: buildCommuterTransactions(),
    limits: { challengeAboveCents: 8_000, hardLimitCents: 30_000 },
  },
];

export const DEFAULT_PROFILE_ID = "maya";
export const DEFAULT_WEEK = snapshot.week;

export function findProfile(id: string): SimulatedProfile | undefined {
  return profiles.find((p) => p.id === id);
}
